 * Next per-project issue number. Archived issues keep their number, so the
 * max is taken over every row rather than the live ones. A purged issue's
 * number is remembered in `project_issue_sequences`, which keeps the sequence
 * moving forward even when the purge removed the project's highest number.
 */
export async function nextIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const db = getDb();
  const row = db
    .select({ value: sql<number | null>`max(${issues.number})` })
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
    )
    .get();
  const purged = db
    .select({ value: projectIssueSequences.lastNumber })
    .from(projectIssueSequences)
    .where(
      and(
        orgPredicate(projectIssueSequences.orgId, orgId),
        eq(projectIssueSequences.projectId, projectId),
      ),
    )
    .get();
  return Math.max(row?.value ?? 0, purged?.value ?? 0) + 1;
}

