 * Clears `archived_at`. Returns `null` when the issue is missing or already
 * live, so two racing restores cannot both succeed.
 */
export async function restoreIssue(
  orgId: OrgId,
  issueId: IssueId,
): Promise<Issue | null> {
  const row = getDb()
    .update(issues)
    .set(restorePatch())
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        eq(issues.id, issueId),
        isNotNull(issues.archivedAt),
      ),
    )
    .returning()
    .get();

