/**
 * The permanent-deletion path of the retention sweep: expired issues and everything hanging off them.
 *
 * Must call (do not reimplement): orgPredicate
 */
import { and, asc, eq, inArray, isNotNull, lte, sql } from "drizzle-orm";
import {
  attachments,
  comments,
  getDb,
  issueLabels,
  issues,
  organizationUsage,
  projectIssueSequences,
  searchIndex,
} from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import type { IsoTimestamp, IssueId, OrgId } from "@/types/common";

const BYTES_PER_MB = 1024 * 1024;

export type PurgeSummary = {
  /** Issues actually deleted; ids that were restored in the meantime are skipped. */
  readonly issues: number;
  /** Megabytes handed back to the storage counter. */
  readonly storageMb: number;
};

/**
 * The oldest archived issues archived at or before `cutoff`, across every
 * project of the org. Callers page through by purging what they get: a purged
 * row is gone, so the next call starts with the following ones.
 */
export async function listExpiredIssueIds(
  orgId: OrgId,
  cutoff: IsoTimestamp,
  limit: number,
): Promise<readonly IssueId[]> {
  const rows = getDb()
    .select({ id: issues.id })
    .from(issues)
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        isNotNull(issues.archivedAt),
        lte(issues.archivedAt, cutoff),
      ),
    )
    .orderBy(asc(issues.archivedAt), asc(issues.id))
    .limit(Math.max(1, limit))
    .all();

  return rows.map((row) => row.id as IssueId);
}

/**
 * Deletes archived issues for good — their label links, comments and
 * attachments, and the search documents of the issues and of those comments —
 * in one transaction, so a failure leaves either all of it or none of it.
 *
 * Three pieces of bookkeeping ride along:
 *  - each project's highest purged issue number is recorded, so numbering
 *    never comes back to it;
 *  - the attachments' megabytes (each rounded up on its own, exactly as
 *    `addAttachment` counted them) leave the storage counter;
 *  - the issues-used counter is left alone: archived issues were never in it.
 *
 * Only rows that are still archived are touched, so an issue restored between
 * listing and purging survives.
 */
export async function purgeArchivedIssues(
  orgId: OrgId,
  issueIds: readonly IssueId[],
): Promise<PurgeSummary> {
  if (issueIds.length === 0) return { issues: 0, storageMb: 0 };

  return getDb().transaction((tx) => {
    const doomed = tx
      .select({
        id: issues.id,
        projectId: issues.projectId,
        number: issues.number,
      })
      .from(issues)
      .where(
        and(
          orgPredicate(issues.orgId, orgId),
          inArray(issues.id, [...issueIds]),
          isNotNull(issues.archivedAt),
        ),
      )
      .all();
    if (doomed.length === 0) return { issues: 0, storageMb: 0 };

    const ids = doomed.map((row) => row.id);

    const storageMb = tx
      .select({ sizeBytes: attachments.sizeBytes })
      .from(attachments)
      .where(
        and(
          orgPredicate(attachments.orgId, orgId),
          inArray(attachments.issueId, ids),
        ),
      )
      .all()
      .reduce((total, row) => total + Math.ceil(row.sizeBytes / BYTES_PER_MB), 0);

    // Search documents first: the comment ids are read off the comments table.
    tx.delete(searchIndex)
      .where(
        and(
          orgPredicate(searchIndex.orgId, orgId),
          eq(searchIndex.subjectKind, "comment"),
          inArray(
            searchIndex.subjectId,
            tx
              .select({ id: comments.id })
              .from(comments)
              .where(
                and(
                  orgPredicate(comments.orgId, orgId),
                  inArray(comments.issueId, ids),
                ),
              ),
          ),
        ),
      )
      .run();
    tx.delete(searchIndex)
      .where(
        and(
          orgPredicate(searchIndex.orgId, orgId),
          eq(searchIndex.subjectKind, "issue"),
          inArray(searchIndex.subjectId, ids),
        ),
      )
      .run();

    const highest = new Map<string, number>();
    for (const row of doomed) {
      highest.set(row.projectId, Math.max(highest.get(row.projectId) ?? 0, row.number));
    }
    for (const [projectId, lastNumber] of highest) {
      tx.insert(projectIssueSequences)
        .values({ projectId, orgId, lastNumber })
        .onConflictDoUpdate({
          target: projectIssueSequences.projectId,
          set: {
            lastNumber: sql`max(${projectIssueSequences.lastNumber}, excluded.last_number)`,
          },
        })
        .run();
    }

    tx.delete(issueLabels)
      .where(
        and(orgPredicate(issueLabels.orgId, orgId), inArray(issueLabels.issueId, ids)),
      )
      .run();
    tx.delete(comments)
      .where(and(orgPredicate(comments.orgId, orgId), inArray(comments.issueId, ids)))
      .run();
    tx.delete(attachments)
      .where(
        and(orgPredicate(attachments.orgId, orgId), inArray(attachments.issueId, ids)),
      )
      .run();

    // Sub-issues outlive their parent; they must not point at a row that is gone.
    tx.update(issues)
      .set({ parentId: null })
      .where(and(orgPredicate(issues.orgId, orgId), inArray(issues.parentId, ids)))
      .run();
    tx.delete(issues)
      .where(and(orgPredicate(issues.orgId, orgId), inArray(issues.id, ids)))
      .run();

    if (storageMb > 0) {
      tx.update(organizationUsage)
        .set({
          storageMbUsed: sql`max(0, ${organizationUsage.storageMbUsed} - ${storageMb})`,
          measuredAt: toIsoTimestamp(new Date()),
        })
        .where(eq(organizationUsage.orgId, orgId))
        .run();
    }

    return { issues: ids.length, storageMb };
  });
}

