body='''const ORG_BATCH = 25;
/** Issues deleted per transaction; the sweep loops until none are left. */
const PURGE_BATCH = 100;

const logger = createLogger("cleanup-archived-job");

/**
 * The retention sweep. An archived issue sits in the trash for as long as the
 * plan promises and no longer: the cut-off comes from `retentionDays`, so an
 * enterprise tenant keeps years of history where a free one keeps a month.
 *
 * Every issue past the cut-off — in every project, however many there are — is
 * deleted for good with its label links, comments, attachments and search
 * documents (see `purgeArchivedIssues`), and the audit rows past the window are
 * purged outright. Once an issue is gone it can no longer be restored.
 */
export async function runCleanupArchivedJob(now: Date): Promise<JobResult> {
  return runJob("cleanup-archived", async (result) => {
    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);

    for (const orgId of orgIds) {
      const org = await orgRepo.findOrgById(orgId);
      if (!org) continue;

      const { retentionDays } = getPlanLimits(org.plan);
      const cutoff = expiryCutoff(now, retentionDays);

      try {
        for (;;) {
          const expired = await retentionRepo.listExpiredIssueIds(
            orgId,
            cutoff,
            PURGE_BATCH,
          );
          if (expired.length === 0) break;

          const purged = await retentionRepo.purgeArchivedIssues(orgId, expired);
          if (purged.issues === 0) break;
          result.processed += purged.issues;
        }
      } catch (error) {
        result.failed += 1;
        logger.error("issue purge failed", {
          orgId,
          reason: error instanceof Error ? error.message : String(error),
        });
      }

      try {
        const purged = await activityRepo.purgeActivityBefore(orgId, cutoff);
        result.processed += purged;
      } catch (error) {
        result.failed += 1;
        logger.error("activity purge failed", {
          orgId,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}
