/**
 * The issue trash: an archived issue can be restored while it is inside the
 * plan's `retentionDays` window, and the retention sweep deletes it for good
 * once the window has closed.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);

import { eq } from "drizzle-orm";
import { getPlanLimits } from "@/config/plan-limits";
import { toAppError } from "@/lib/errors";
import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { RestoreRefusedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import { attachments, comments, getDb, issueLabels, issues } from "@/server/db";
import { runCleanupArchivedJob } from "@/server/jobs/cleanup-archived-job";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { registerActivityListeners } from "@/server/services/activity-service";
import * as attachmentService from "@/server/services/attachment-service";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import { registerSearchListeners } from "@/server/services/search-service";
import { NotFoundError } from "@/server/services/_support";
import { registerUsageListeners } from "@/server/services/usage-service";
import { createTenant, issueInput, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";
import type { IsoTimestamp, IssueId, ProjectId } from "@/types/common";
import type { Issue } from "@/types/issue";
import type { PlanId } from "@/types/billing";
import type { Unsubscribe } from "@/types/event";

const MB = 1024 * 1024;
const DAY_MS = 24 * 60 * 60 * 1000;

let cleanup: () => void;
const detachers: Unsubscribe[] = [];
let slugCounter = 0;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detachers.push(
    registerUsageListeners(),
    registerSearchListeners(),
    registerActivityListeners(),
  );
});

afterAll(() => {
  while (detachers.length > 0) detachers.pop()?.();
  cleanup();
});

afterEach(() => {
  vi.useRealTimers();
});

async function tenantOn(plan: PlanId): Promise<Tenant> {
  slugCounter += 1;
  const tenant = await createTenant(`trash${slugCounter}`, plan);
  await usageRepo.getUsage(tenant.org.id);
  return tenant;
}

async function newIssue(
  tenant: Tenant,
  title: string,
  projectId: ProjectId = tenant.project.id,
): Promise<Issue> {
  return issueService.createIssue(
    tenant.actors.member,
    issueInput(tenant.org.id, projectId, { title }),
  );
}

async function archiveAgo(
  tenant: Tenant,
  issue: Issue,
  ageMs: number,
): Promise<Issue> {
  await issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id);
  const archivedAt = new Date(Date.now() - ageMs).toISOString() as IsoTimestamp;
  getDb().update(issues).set({ archivedAt }).where(eq(issues.id, issue.id)).run();
  return (await issueRepo.findIssueById(tenant.org.id, issue.id)) as Issue;
}

function retentionMs(plan: PlanId): number {
  return getPlanLimits(plan).retentionDays * DAY_MS;
}

async function restoreOutcome(tenant: Tenant, issueId: IssueId) {
  try {
    await issueService.restoreIssue(tenant.actors.member, tenant.org.id, issueId);
    return "restored";
  } catch (error) {
    return error instanceof RestoreRefusedError ? error.reason : error;
  }
}

describe("restoring an archived issue", () => {
  it("makes it live again with its number, and every subscriber reacts", async () => {
    const tenant = await tenantOn("free");
    const issue = await newIssue(tenant, "Findable again");
    await archiveAgo(tenant, issue, 1_000);

    expect(await searchRepo.countIndexed(tenant.org.id)).toBe(0);
    const before = await usageRepo.getUsage(tenant.org.id);

    const seen: unknown[] = [];
    const off = subscribe("issue.restored", (payload) => {
      seen.push(payload);
    });
    const restored = await issueService.restoreIssue(
      tenant.actors.member,
      tenant.org.id,
      issue.id,
    );
    off();

    expect(restored.archivedAt).toBeNull();
    expect(restored.number).toBe(issue.number);
    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({
      orgId: tenant.org.id,
      actorId: tenant.userIds.member,
      issueId: issue.id,
      projectId: issue.projectId,
    });

    const after = await usageRepo.getUsage(tenant.org.id);
    expect(after.issuesUsed).toBe(before.issuesUsed + 1);
    expect(await searchRepo.countIndexed(tenant.org.id)).toBe(1);

    const audit = await activityRepo.listActivityForSubject(
      tenant.org.id,
      "issue",
      issue.id,
    );
    expect(audit.map((row) => row.action)).toContain("issue.restored");
  });

  it("is refused when the issue is not archived", async () => {
    const tenant = await tenantOn("free");
    const issue = await newIssue(tenant, "Live");
    expect(await restoreOutcome(tenant, issue.id)).toBe("not_archived");
  });

  it("stays possible until retentionDays × 24h have passed, then expires", async () => {
    const tenant = await tenantOn("free");
    const inside = await newIssue(tenant, "Just inside");
    const outside = await newIssue(tenant, "Just outside");
    const window = retentionMs("free");

    await archiveAgo(tenant, inside, window - 60_000);
    await archiveAgo(tenant, outside, window + 60_000);

    expect(await restoreOutcome(tenant, inside.id)).toBe("restored");
    expect(await restoreOutcome(tenant, outside.id)).toBe("expired");

    // Refused means untouched: still archived, nothing indexed or counted.
    const stillArchived = await issueRepo.findIssueById(tenant.org.id, outside.id);
    expect(stillArchived?.archivedAt).not.toBeNull();
  });

  it("uses the workspace plan's window", async () => {
    const tenant = await tenantOn("starter");
    const issue = await newIssue(tenant, "Older than free allows");
    await archiveAgo(tenant, issue, retentionMs("free") + DAY_MS);
    expect(await restoreOutcome(tenant, issue.id)).toBe("restored");
  });

  it("is refused while the project is archived", async () => {
    const tenant = await tenantOn("growth");
    const issue = await newIssue(tenant, "Orphaned by its project");
    await archiveAgo(tenant, issue, 1_000);
    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      archiveIssues: false,
    });

    expect(await restoreOutcome(tenant, issue.id)).toBe("project_archived");

    await projectService.restoreProject(
      tenant.actors.admin,
      tenant.org.id,
      tenant.project.id,
    );
    expect(await restoreOutcome(tenant, issue.id)).toBe("restored");
  });

  it("is refused when the project has no room, counted as createIssue counts", async () => {
    const tenant = await tenantOn("free");
    const limit = getPlanLimits("free").issuesPerProject;
    const archived = await newIssue(tenant, "No room");
    await archiveAgo(tenant, archived, 1_000);

    for (let i = 0; i < limit; i += 1) await newIssue(tenant, `Filler ${i}`);
    await expect(newIssue(tenant, "One too many")).rejects.toThrow();

    const seen: unknown[] = [];
    const off = subscribe("issue.restored", (payload) => {
      seen.push(payload);
    });
    expect(await restoreOutcome(tenant, archived.id)).toBe("quota");
    off();

    expect(seen).toHaveLength(0);
    const row = await issueRepo.findIssueById(tenant.org.id, archived.id);
    expect(row?.archivedAt).not.toBeNull();
  });

  it("guards tenant scope, existence and permission like archiving does", async () => {
    const tenant = await tenantOn("free");
    const other = await tenantOn("free");
    const issue = await newIssue(tenant, "Guarded");
    await archiveAgo(tenant, issue, 1_000);

    await expect(
      issueService.restoreIssue(tenant.actors.member, other.org.id, issue.id),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      issueService.restoreIssue(
        tenant.actors.member,
        tenant.org.id,
        "01HZZZNOSUCHISSUE000000000" as IssueId,
      ),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      issueService.restoreIssue(tenant.actors.viewer, tenant.org.id, issue.id),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
  });

  it("lets the author restore whatever their role", async () => {
    const tenant = await tenantOn("free");
    const issue = await issueService.createIssue(
      tenant.actors.viewer,
      issueInput(tenant.org.id, tenant.project.id, { title: "Viewer's own" }),
    ).catch(() => null);
    // Viewers cannot create; the ownership escalation is exercised through
    // the assignee instead.
    expect(issue).toBeNull();

    const assigned = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Assigned to a viewer",
        assigneeId: tenant.userIds.viewer,
      }),
    );
    await archiveAgo(tenant, assigned, 1_000);

    const restored = await issueService.restoreIssue(
      tenant.actors.viewer,
      tenant.org.id,
      assigned.id,
    );
    expect(restored.archivedAt).toBeNull();
  });

  it("maps a refusal to the conflict code", () => {
    const shape = toAppError(new RestoreRefusedError("expired"));
    expect(shape.code).toBe("conflict");
    expect(new RestoreRefusedError("quota").code).toBe("conflict");
    expect(new RestoreRefusedError("quota").reason).toBe("quota");
  });
});

describe("the retention sweep", () => {
  const NOW = () => new Date();

  it("purges every expired issue with its comments, attachments and search documents", async () => {
    const tenant = await tenantOn("free");
    const second = await projectRepo.insertProject({
      orgId: tenant.org.id,
      name: "Second",
      slug: "second",
      key: "SEC",
      description: null,
      visibility: "org",
      leadId: tenant.userIds.owner,
      color: "#6366f1",
      targetDate: null,
    });
    const window = retentionMs("free");

    const kept = await newIssue(tenant, "Live one");
    const recent = await archiveAgo(tenant, await newIssue(tenant, "Recently archived"), window - DAY_MS);
    const doomedA = await archiveAgo(tenant, await newIssue(tenant, "Expired A"), window + DAY_MS);
    const doomedB = await archiveAgo(
      tenant,
      await newIssue(tenant, "Expired B", second.id),
      window + 2 * DAY_MS,
    );

    for (const issue of [doomedA, doomedB, recent]) {
      await commentService.createComment(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        body: `Comment on ${issue.title}`,
        parentId: null,
        mentionedUserIds: [],
      });
    }
    for (const [issue, sizeBytes] of [
      [doomedA, MB * 3 + 1],
      [doomedA, 10],
      [doomedB, MB],
      [recent, 100],
    ] as const) {
      await attachmentService.addAttachment(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        filename: "file.bin",
        contentType: "application/octet-stream",
        sizeBytes,
      });
    }
    await searchRepo.upsertSearchDocument(tenant.org.id, "issue", doomedB.id, "Expired B", second.id);
    getDb()
      .insert(issueLabels)
      .values({ orgId: tenant.org.id, issueId: doomedA.id, labelId: "01HZZZLABEL0000000000000000" })
      .run();

    const usageBefore = await usageRepo.getUsage(tenant.org.id);
    expect(usageBefore.storageMbUsed).toBe(4 + 1 + 1 + 1);

    const result = await runCleanupArchivedJob(NOW());
    expect(result.failed).toBe(0);

    const all = await issueRepo.listIssues({
      orgId: tenant.org.id,
      limit: 100,
      cursor: null,
      includeArchived: true,
    });
    expect(all.items.map((issue) => issue.id).sort()).toEqual(
      [kept.id, recent.id].sort(),
    );

    const db = getDb();
    const commentRows = db.select().from(comments).where(eq(comments.orgId, tenant.org.id)).all();
    expect(commentRows.map((row) => row.issueId)).toEqual([recent.id]);
    const attachmentRows = db.select().from(attachments).where(eq(attachments.orgId, tenant.org.id)).all();
    expect(attachmentRows.map((row) => row.issueId)).toEqual([recent.id]);
    expect(db.select().from(issueLabels).where(eq(issueLabels.orgId, tenant.org.id)).all()).toHaveLength(0);

    // Kept: the live issue's and the recent issue's documents (the latter was
    // removed when it was archived, so only the live issue and comment remain).
    const remaining = await searchRepo.searchDocuments({
      orgId: tenant.org.id,
      q: "",
      kinds: [],
      limit: 100,
      cursor: null,
    });
    const subjects = remaining.items.map((row) => `${row.subjectKind}:${row.subjectId}`).sort();
    const commentOfRecent = commentRows[0]?.id;
    expect(subjects).toEqual([`comment:${commentOfRecent}`, `issue:${kept.id}`].sort());

    const usageAfter = await usageRepo.getUsage(tenant.org.id);
    expect(usageAfter.issuesUsed).toBe(usageBefore.issuesUsed);
    expect(usageAfter.storageMbUsed).toBe(1);
    const recount = await usageRepo.recomputeUsage(tenant.org.id);
    expect(usageAfter.storageMbUsed).toBe(recount.storageMbUsed);
  });

  it("purges every expired issue however many there are", async () => {
    const tenant = await tenantOn("enterprise");
    const window = retentionMs("enterprise");
    const total = 230;
    const stamp = new Date(Date.now() - window - DAY_MS).toISOString();

    const db = getDb();
    for (let i = 0; i < total; i += 1) {
      const issue = await newIssue(tenant, `Bulk ${i}`);
      db.update(issues)
        .set({ archivedAt: stamp })
        .where(eq(issues.id, issue.id))
        .run();
    }

    const result = await runCleanupArchivedJob(NOW());
    expect(result.failed).toBe(0);
    expect(
      await issueRepo.countIssues(tenant.org.id, tenant.project.id, {
        includeArchived: true,
      }),
    ).toBe(0);
  });

  it("never reuses a number, even the highest one", async () => {
    const tenant = await tenantOn("free");
    const window = retentionMs("free");
    await newIssue(tenant, "One");
    const top = await newIssue(tenant, "Two");
    await archiveAgo(tenant, top, window + DAY_MS);

    await runCleanupArchivedJob(NOW());
    expect(await issueRepo.findIssueById(tenant.org.id, top.id)).toBeNull();

    const next = await newIssue(tenant, "Three");
    expect(next.number).toBe(top.number + 1);

    // …and it keeps holding after a second purge of a lower number.
    await archiveAgo(tenant, next, window + DAY_MS);
    await runCleanupArchivedJob(NOW());
    const after = await newIssue(tenant, "Four");
    expect(after.number).toBe(next.number + 1);
  });

  it("makes a purged issue unrestorable", async () => {
    const tenant = await tenantOn("free");
    const issue = await newIssue(tenant, "Gone for good");
    await archiveAgo(tenant, issue, retentionMs("free") + DAY_MS);

    await runCleanupArchivedJob(NOW());

    await expect(
      issueService.restoreIssue(tenant.actors.member, tenant.org.id, issue.id),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("only touches its own workspace's expired issues", async () => {
    const tenant = await tenantOn("free");
    const enterprise = await tenantOn("enterprise");
    const age = retentionMs("free") + DAY_MS;

    const freeIssue = await archiveAgo(tenant, await newIssue(tenant, "Free, expired"), age);
    const bigIssue = await archiveAgo(enterprise, await newIssue(enterprise, "Enterprise, still fresh"), age);

    await runCleanupArchivedJob(NOW());

    expect(await issueRepo.findIssueById(tenant.org.id, freeIssue.id)).toBeNull();
    expect(await issueRepo.findIssueById(enterprise.org.id, bigIssue.id)).not.toBeNull();
